import React, { useEffect } from "react";
import { Route, Routes } from "react-router-dom";
import Home from "./pages/Home";
import Layout from "./pages/Layout";
import Dashboard from "./pages/Dashboard";
import ResumeBuilder from "./pages/ResumeBuilder";
import Preview from "./pages/Preview";
import Login from "./pages/Login";
import { useDispatch } from "react-redux";
import api from "./configs/api.js";
import { login, setLoading } from "./app/features/authSlice.js";
import { Toaster } from "react-hot-toast";

const App = () => {
  const dispatch = useDispatch();

  const getUserData = async () => {
    const token = localStorage.getItem("token");
    try {
      if (token) {
        const { data } = await api.get("/api/users/data", {
          headers: { Authorization: token },
        });
        if (data.user) {
          dispatch(login({ token, user: data.user }));
        }
        dispatch(setLoading(false));
      } else {
        dispatch(setLoading(false));
      }
    } catch (error) {
      dispatch(setLoading(false));
      console.log(error.message);
    }
  };

  useEffect(() => {
    getUserData();
  }, []);

  return (
    <>
      <Toaster />

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="app" element={<Layout />}>
          <Route index element={<Dashboard />} />
          <Route path="builder/:resumeId" element={<ResumeBuilder />} />
        </Route>

        <Route path="view/:resumeId" element={<Preview />} />
      </Routes>
    </>
  );
};

export default App;

import React from "react";

const ATSCleanTemplate = ({ data, accentColor = "#111827" }) => {
  const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const [year, month] = dateStr.split("-");
    if (!month) return dateStr;
    return new Date(year, month - 1).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
    });
  };

  return (
    <div className="max-w-4xl mx-auto p-8 bg-white text-black font-sans leading-relaxed text-sm">
      {/* Name and Contact (Plain Clean Stack for ATS Parsers) */}
      <div className="text-center mb-6 pb-4 border-b border-gray-800">
        <h1 className="text-2xl font-bold uppercase tracking-wider text-black mb-1">
          {data.personal_info?.full_name || "FIRSTNAME LASTNAME"}
        </h1>
        {data.personal_info?.profession && (
          <p className="font-semibold text-gray-800 mb-2">
            {data.personal_info.profession}
          </p>
        )}
        <div className="text-xs text-gray-800 space-x-2">
          {data.personal_info?.location && <span>{data.personal_info.location}</span>}
          {data.personal_info?.phone && <span> | {data.personal_info.phone}</span>}
          {data.personal_info?.email && <span> | {data.personal_info.email}</span>}
          {data.personal_info?.linkedin && <span> | {data.personal_info.linkedin}</span>}
        </div>
      </div>

      {/* Summary */}
      {data.professional_summary && (
        <div className="mb-5">
          <h2 className="text-xs font-bold uppercase tracking-wider border-b border-black pb-0.5 mb-2 text-black">
            Professional Summary
          </h2>
          <p className="text-xs text-gray-900 leading-relaxed">
            {data.professional_summary}
          </p>
        </div>
      )}

      {/* Skills */}
      {data.skills && data.skills.length > 0 && (
        <div className="mb-5">
          <h2 className="text-xs font-bold uppercase tracking-wider border-b border-black pb-0.5 mb-2 text-black">
            Technical & Professional Skills
          </h2>
          <p className="text-xs text-gray-900">
            <span className="font-semibold">Core Competencies:</span> {data.skills.join(", ")}
          </p>
        </div>
      )}

      {/* Work Experience */}
      {data.experience && data.experience.length > 0 && (
        <div className="mb-5">
          <h2 className="text-xs font-bold uppercase tracking-wider border-b border-black pb-0.5 mb-3 text-black">
            Work Experience
          </h2>
          <div className="space-y-4">
            {data.experience.map((exp, index) => (
              <div key={index} className="text-xs">
                <div className="flex justify-between font-bold text-black">
                  <span>{exp.company}</span>
                  <span>
                    {formatDate(exp.start_date)} - {exp.is_current ? "Present" : formatDate(exp.end_date)}
                  </span>
                </div>
                <div className="italic text-gray-800 font-semibold mb-1">{exp.position}</div>
                {exp.description && (
                  <div className="text-gray-900 leading-relaxed whitespace-pre-line pl-3">
                    {exp.description}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Education */}
      {data.education && data.education.length > 0 && (
        <div className="mb-5">
          <h2 className="text-xs font-bold uppercase tracking-wider border-b border-black pb-0.5 mb-3 text-black">
            Education
          </h2>
          <div className="space-y-3">
            {data.education.map((edu, index) => (
              <div key={index} className="text-xs">
                <div className="flex justify-between font-bold text-black">
                  <span>{edu.institution}{edu.location ? `, ${edu.location}` : ""}</span>
                  <span>
                    {edu.start_date ? `${formatDate(edu.start_date)} - ` : ""}
                    {edu.is_current ? "Present" : formatDate(edu.graduation_date)}
                  </span>
                </div>
                <div className="italic text-gray-800">
                  {edu.degree} {edu.field && `in ${edu.field}`} {edu.gpa && `(GPA: ${edu.gpa})`}
                </div>
                {edu.honors && <p className="text-gray-700">Honors: {edu.honors}</p>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Projects */}
      {data.project && data.project.length > 0 && (
        <div className="mb-5">
          <h2 className="text-xs font-bold uppercase tracking-wider border-b border-black pb-0.5 mb-2 text-black">
            Key Projects
          </h2>
          <div className="space-y-2">
            {data.project.map((proj, index) => (
              <div key={index} className="text-xs">
                <span className="font-bold text-black">{proj.name}: </span>
                <span className="text-gray-900">{proj.description}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default ATSCleanTemplate;

import React from "react";
import { Mail, Phone, MapPin, Linkedin, Globe, Award, CheckCircle } from "lucide-react";

const NovoExecutiveTemplate = ({ data, accentColor = "#0f172a" }) => {
  const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const [year, month] = dateStr.split("-");
    if (!month) return dateStr;
    return new Date(year, month - 1).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
    });
  };

  const certifications = data.certifications || [];
  const customSections = data.custom_sections || [];

  return (
    <div className="max-w-4xl mx-auto bg-white text-gray-900 font-sans shadow-md p-10 leading-relaxed">
      {/* Executive Banner Header */}
      <header className="bg-slate-900 text-white p-8 rounded-xl mb-8 flex justify-between items-center shadow-sm">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-white mb-1">
            {data.personal_info?.full_name || "EXECUTIVE NAME"}
          </h1>
          <p className="text-sm text-blue-300 font-semibold tracking-wide uppercase">
            {data.personal_info?.profession || "CHIEF EXECUTIVE / SENIOR DIRECTOR"}
          </p>

          <div className="flex flex-wrap gap-4 text-xs text-slate-300 mt-4">
            {data.personal_info?.email && <span>{data.personal_info.email}</span>}
            {data.personal_info?.phone && <span>• {data.personal_info.phone}</span>}
            {data.personal_info?.location && <span>• {data.personal_info.location}</span>}
            {data.personal_info?.linkedin && <span>• {data.personal_info.linkedin}</span>}
          </div>
        </div>

        {data.personal_info?.image && (
          <img
            src={data.personal_info.image}
            alt="Executive Headshot"
            className="w-24 h-24 rounded-lg object-cover border-2 border-white/30 shrink-0"
          />
        )}
      </header>

      {/* Executive Summary & Core Strengths */}
      {data.professional_summary && (
        <section className="mb-6">
          <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-2">
            Executive Summary & Vision
          </h2>
          <p className="text-xs text-gray-800 leading-relaxed text-justify">
            {data.professional_summary}
          </p>
        </section>
      )}

      {/* Key Skills & Executive Competencies */}
      {data.skills && data.skills.length > 0 && (
        <section className="mb-6">
          <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-3">
            Core Leadership & Strategic Competencies
          </h2>
          <div className="grid grid-cols-3 gap-2">
            {data.skills.map((skill, idx) => (
              <div key={idx} className="p-2 border border-slate-200 rounded-md bg-slate-50 text-xs font-semibold text-slate-800 text-center">
                {skill}
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Executive Experience */}
      {data.experience && data.experience.length > 0 && (
        <section className="mb-6">
          <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-4">
            Executive Leadership & Experience
          </h2>

          <div className="space-y-5">
            {data.experience.map((exp, index) => (
              <div key={index} className="text-xs">
                <div className="flex justify-between items-baseline font-bold text-slate-900 text-sm">
                  <span>{exp.position}</span>
                  <span className="text-xs text-gray-500 font-normal">
                    {formatDate(exp.start_date)} - {exp.is_current ? "Present" : formatDate(exp.end_date)}
                  </span>
                </div>
                <div className="text-blue-800 font-semibold mb-1 text-xs">{exp.company}</div>
                {exp.description && (
                  <div className="text-gray-800 leading-relaxed whitespace-pre-line text-justify pl-3 border-l-2 border-slate-900">
                    {exp.description}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Education & Credentials */}
      <div className="grid md:grid-cols-2 gap-6 mb-6">
        {data.education && data.education.length > 0 && (
          <section>
            <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-3">
              Education & Degrees
            </h2>

            <div className="space-y-3 text-xs">
              {data.education.map((edu, index) => (
                <div key={index}>
                  <div className="font-bold text-slate-900">{edu.degree} {edu.field && `in ${edu.field}`}</div>
                  <div className="text-gray-700">{edu.institution}</div>
                  <div className="text-gray-500 text-[11px]">
                    {formatDate(edu.start_date)} - {edu.is_current ? "Present" : formatDate(edu.graduation_date)}
                  </div>
                  {edu.honors && <div className="text-green-700 font-medium">Honors: {edu.honors}</div>}
                </div>
              ))}
            </div>
          </section>
        )}

        {certifications.length > 0 && (
          <section>
            <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-3">
              Board Roles & Certifications
            </h2>

            <div className="space-y-2 text-xs">
              {certifications.map((cert, idx) => (
                <div key={idx} className="p-2 border border-slate-200 rounded-md bg-slate-50">
                  <div className="font-bold text-slate-900">{cert.name}</div>
                  <div className="text-gray-600 text-[11px]">{cert.issuer} {cert.date && `(${cert.date})`}</div>
                </div>
              ))}
            </div>
          </section>
        )}
      </div>

      {/* Custom Sections */}
      {customSections.map((sec, idx) => (
        <section key={idx} className="mb-6">
          <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 pb-1 border-b-2 border-slate-900 mb-3">
            {sec.title}
          </h2>
          <div className="space-y-2 text-xs">
            {sec.items?.map((item, i) => (
              <div key={i}>
                <div className="font-bold text-slate-900">{item.heading} {item.date && `(${item.date})`}</div>
                {item.subheading && <div className="text-gray-700 italic">{item.subheading}</div>}
                {item.description && <div className="text-gray-700">{item.description}</div>}
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
};

export default NovoExecutiveTemplate;

import React from "react";

const OfficialLetterheadTemplate = ({ data, accentColor = "#1e3a8a" }) => {
  const letterhead = data.letterhead || {};
  const documentBody = data.document_body || "";
  const signatureUrl = data.signature_url || "";
  const docType = data.document_type || "recommendation_letter";

  const defaultDate = letterhead.date || new Date().toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });

  return (
    <div className="max-w-4xl mx-auto p-12 bg-white text-gray-900 font-serif leading-relaxed shadow-sm min-h-[11in] flex flex-col justify-between">
      <div>
        {/* Institutional Letterhead Header */}
        <header className="border-b-2 pb-6 mb-8 flex justify-between items-start" style={{ borderColor: accentColor }}>
          <div className="flex items-center gap-4">
            {letterhead.logo_url && (
              <img
                src={letterhead.logo_url}
                alt="Institutional Logo"
                className="h-16 w-auto object-contain"
              />
            )}
            <div>
              <h1 className="text-2xl font-bold tracking-tight uppercase" style={{ color: accentColor }}>
                {letterhead.institution_name || "HARVARD UNIVERSITY"}
              </h1>
              <p className="text-sm font-semibold text-gray-700">
                {letterhead.sender_title || "OFFICE OF ACADEMIC AFFAIRS & RESEARCH"}
              </p>
              <p className="text-xs text-gray-500 italic mt-0.5">
                {letterhead.sender_name || "Official Departmental Communication"}
              </p>
            </div>
          </div>

          <div className="text-right text-xs text-gray-600 space-y-0.5">
            {letterhead.sender_email && <p>Email: {letterhead.sender_email}</p>}
            {letterhead.sender_phone && <p>Phone: {letterhead.sender_phone}</p>}
            <p className="text-gray-400 text-[10px]">Doc Ref: #{data._id ? data._id.slice(-6).toUpperCase() : "OFFICIAL"}</p>
          </div>
        </header>

        {/* Date Line */}
        <div className="mb-6 text-sm font-sans text-gray-800">
          <p>{defaultDate}</p>
        </div>

        {/* Recipient Address Block */}
        {(letterhead.recipient_name || letterhead.recipient_organization || letterhead.recipient_address) && (
          <div className="mb-6 text-sm font-sans text-gray-800 space-y-0.5">
            {letterhead.recipient_name && <p className="font-bold">{letterhead.recipient_name}</p>}
            {letterhead.recipient_title && <p>{letterhead.recipient_title}</p>}
            {letterhead.recipient_organization && <p className="font-semibold">{letterhead.recipient_organization}</p>}
            {letterhead.recipient_address && <p className="text-gray-600">{letterhead.recipient_address}</p>}
          </div>
        )}

        {/* Subject Line */}
        {letterhead.subject && (
          <div className="mb-6 pb-2 border-b border-gray-200">
            <h2 className="text-sm font-bold uppercase tracking-wide text-gray-900">
              RE: {letterhead.subject}
            </h2>
          </div>
        )}

        {/* Main Document Body */}
        <div className="text-sm text-gray-900 leading-relaxed whitespace-pre-line text-justify mb-8 font-serif">
          {documentBody || (
            <p className="italic text-gray-400">
              (No document body entered yet. Select "Recommendation Letter Builder" or "Official Documents" to generate or write your letter.)
            </p>
          )}
        </div>
      </div>

      {/* Official Sign-Off and Digital Signature Block */}
      <div className="pt-6 border-t border-gray-200 text-sm font-sans mt-auto">
        <p className="font-serif italic mb-4">Sincerely,</p>

        {signatureUrl ? (
          <img
            src={signatureUrl}
            alt="Digital Signature"
            className="h-14 w-auto object-contain mb-2"
          />
        ) : (
          <div className="h-12 w-48 border-b border-dashed border-gray-400 mb-2 flex items-end">
            <span className="text-[10px] text-gray-400 italic mb-1">[Digital Signature]</span>
          </div>
        )}

        <div className="font-bold text-gray-900">
          {letterhead.sender_name || data.personal_info?.full_name || "Signature Name"}
        </div>
        <div className="text-xs text-gray-700">
          {letterhead.sender_title || data.personal_info?.profession || "Official Representative"}
        </div>
        {letterhead.institution_name && (
          <div className="text-xs text-gray-600 italic">
            {letterhead.institution_name}
          </div>
        )}
      </div>
    </div>
  );
};

export default OfficialLetterheadTemplate;

import {
  FilePenLineIcon,
  LoaderCircleIcon,
  PencilIcon,
  PlusIcon,
  TrashIcon,
  UploadCloud,
  XIcon,
} from "lucide-react";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../configs/api.js";
import { useSelector } from "react-redux";
import toast from "react-hot-toast";
import pdfToText from "react-pdftotext";

const Dashboard = () => {
  const { user, token } = useSelector((state) => state.auth);

  const colors = ["#9333ea", "#d97706", "#dc2626", "#0284c7", "#16a34a"];
  const [allResumes, setAllResumes] = useState([]);
  const [showCreateResume, setShowCreateResume] = useState(false);
  const [showUploadResume, setShowUploadResume] = useState(false);
  const [title, setTitle] = useState("");
  const [resume, setResume] = useState(null);
  const [editResumeId, setEditResumeId] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const loadAllResumes = async () => {
    try {
      const { data } = await api.get("/api/users/resumes", {
        headers: {
          Authorization: token,
        },
      });
      setAllResumes(data.resumes);
    } catch (error) {
      toast.error(error?.response?.data?.message || error.message);
    }
  };

  const createResume = async (event) => {
    try {
      event.preventDefault();
      const { data } = await api.post(
        "/api/resumes/create",
        { title },
        {
          headers: {
            Authorization: token,
          },
        }
      );
      setAllResumes([...allResumes, data.resume]);
      setTitle("");
      setShowCreateResume(false);
      navigate(`/app/builder/${data.resume._id}`);
    } catch (error) {
      toast.error(error?.response?.data?.message || error.message);
    }
    setIsLoading(false);
  };

  const uploadResume = async (event) => {
    event.preventDefault();
    setIsLoading(true);
    try {
      const resumeText = await pdfToText(resume);
      const { data } = await api.post(
        "/api/ai/upload-resume",
        { title, resumeText },
        {
          headers: {
            Authorization: token,
          },
        }
      );
      setTitle("");
      setResume(null);
      setShowUploadResume(false);
      navigate(`/app/builder/${data.resume._id}`);
    } catch (error) {
      toast.error(error?.response?.data?.message || error.message);
    }
  };

  const editTitle = async (event) => {
    try {
      event.preventDefault();
      const { data } = await api.put(
        "/api/resumes/update",
        { resumeId: editResumeId, resumeData: { title } },
        { headers: { Authorization: token } }
      );
      setAllResumes(
        allResumes.map((resume) =>
          resume._id === editResumeId ? { ...resume, title } : resume
        )
      );
      setTitle("");
      setEditResumeId("");
      toast.success(data.message);
    } catch (error) {
      toast.error(error?.response?.data?.message || error.message);
    }
    event.preventDefault();
  };

  const deleteResume = async (resumeId) => {
    try {
      const confirm = window.confirm(
        "Are you sure you want to delete this resume?"
      );
      if (confirm) {
        const { data } = await api.delete(`/api/resumes/delete/${resumeId}`, {
          headers: {
            Authorization: token,
          },
        });
        setAllResumes(allResumes.filter((resume) => resume._id !== resumeId));
        toast.success(data.message);
      }
    } catch (error) {
      toast.error(error?.response?.data?.message || error.message);
    }
  };

  useEffect(() => {
    loadAllResumes();
  }, []);

  return (
    <div>
      <div className="max-w-7xl mx-auto px-4 py-8">
        <p className="text-2xl font-medium mb-6 bg-gradient-to-r from-slate-600 to-slate-700 bg-clip-text text-transparent sm:hidden">
          Welcome, John Doe
        </p>

        <div className="flex gap-4">
          <button
            onClick={() => setShowCreateResume(true)}
            className="w-full bg-white sm:max-w-36 h-48 flex flex-col items-center justify-center rounded-lg gap-2 text-slate-600 border border-dashed border-slate-300 group hover:border-indigo-500 hover:shadow-lg transition-all duration-300 cursor-pointer"
          >
            <PlusIcon className="size-11 transition-all duration-300 p-2.5 bg-gradient-to-br from-indigo-300 to-indigo-500 text-white rounded-full" />
            <p className="text-sm group-hover:text-indigo-600 transition-all duration-300">
              Create Resume
            </p>
          </button>
          <button
            onClick={() => setShowUploadResume(true)}
            className="w-full bg-white sm:max-w-36 h-48 flex flex-col items-center justify-center rounded-lg gap-2 text-slate-600 border border-dashed border-slate-300 group hover:border-purple-500 hover:shadow-lg transition-all duration-300 cursor-pointer"
          >
            <UploadCloud className="size-11 transition-all duration-300 p-2.5 bg-gradient-to-br from-purple-300 to-purple-500 text-white rounded-full" />
            <p className="text-sm group-hover:text-purple-600 transition-all duration-300">
              Upload Existing
            </p>
          </button>
        </div>

        <hr className="border-slate-300 my-6 sm:w-[305px]" />

        <div className="grid grid-cols-2 sm:flex flex-wrap gap-4">
          {allResumes.map((resume, index) => {
            const baseColor = colors[index % colors.length];
            return (
              <button
                key={index}
                onClick={() => navigate(`/app/builder/${resume._id}`)}
                className="relative w-full sm:max-w-36 h-48 flex flex-col items-center justify-center rounded-lg gap-2 border group hover:shadow-lg transition-all duration-300 cursor-pointer"
                style={{
                  background: `linear-gradient(135deg, ${baseColor}10, ${baseColor}40) `,
                  borderColor: baseColor + "40",
                }}
              >
                <FilePenLineIcon
                  className="size-7 group-hover:scale-105 transition-all"
                  style={{ color: baseColor }}
                />
                <p
                  className="text-sm group-hover:scale-105 transition-all px-2 text-center"
                  style={{ color: baseColor }}
                >
                  {resume.title}
                </p>
                <p
                  className="absolute bottom-1 text-[11px] text-slate-400 group-hover:text-slate-500 transition-all duration-300 px-2 text-center"
                  style={{ color: baseColor + "90" }}
                >
                  Updated on {new Date(resume.updatedAt).toLocaleDateString()}
                </p>
                <div
                  onClick={(e) => e.stopPropagation()}
                  className="absolute top-1 right-1 group-hover:flex items-center hidden"
                >
                  <TrashIcon
                    onClick={() => deleteResume(resume._id)}
                    className="size-7 p-1.5 hover:bg-white/50 rounded text-slate-700 transition-colors"
                  />
                  <PencilIcon
                    onClick={() => {
                      setEditResumeId(resume._id);
                      setTitle(resume.title);
                    }}
                    className="size-7 p-1.5 hover:bg-white/50 rounded text-slate-700 transition-colors"
                  />
                </div>
              </button>
            );
          })}
        </div>

        {showCreateResume && (
          <form
            onSubmit={createResume}
            onClick={() => setShowCreateResume(false)}
            className="fixed inset-0 bg-black/70 backdrop-blur bg-opacity-50 z-10 flex items-center justify-center"
          >
            <div
              onClick={(e) => e.stopPropagation()}
              className="relative bg-slate-50 border shadow-md rounded-lg w-full max-w-sm p-6"
            >
              <h2 className="text-xl font-bold mb-4">Create a Resume</h2>
              <input
                onChange={(e) => setTitle(e.target.value)}
                value={title}
                type="text"
                placeholder="Enter resume title"
                className="w-full px-4 py-2 mb-4 focus:border-green-600 ring-green-600"
                required
              />

              <button className="w-full py-2 bg-green-600 text-white rounded hover:bg-green-700 transition-colors">
                Create Resume
              </button>
              <XIcon
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 cursor-pointer transition-colors"
                onClick={() => {
                  setShowCreateResume(false);
                  setTitle("");
                }}
              />
            </div>
          </form>
        )}

        {showUploadResume && (
          <form
            onSubmit={uploadResume}
            onClick={() => setShowUploadResume(false)}
            className="fixed inset-0 bg-black/70 backdrop-blur bg-opacity-50 z-10 flex items-center justify-center"
          >
            <div
              onClick={(e) => e.stopPropagation()}
              className="relative bg-slate-50 border shadow-md rounded-lg w-full max-w-sm p-6"
            >
              <h2 className="text-xl font-bold mb-4">Upload Resume</h2>
              <input
                onChange={(e) => setTitle(e.target.value)}
                value={title}
                type="text"
                placeholder="Enter resume title"
                className="w-full px-4 py-2 mb-4 focus:border-green-600 ring-green-600"
                required
              />

              <div>
                <label
                  htmlFor="resume-input"
                  className="block text-sm text-slate-700"
                >
                  Select resume file
                  <div className="flex flex-col items-center justify-center gap-2 border group text-slate-400 border-slate-400 border-dashed rounded-md p-4 py-10 my-4 hover:border-green-500 hover:text-green-700 cursor-pointer transition-colors">
                    {resume ? (
                      <p className="text-green-700">{resume.name}</p>
                    ) : (
                      <>
                        <UploadCloud className="size-14 stroke-1" />
                        <p>Upload Resume</p>
                      </>
                    )}
                  </div>
                </label>
                <input
                  type="file"
                  id="resume-input"
                  accept=".pdf"
                  hidden
                  onChange={(e) => setResume(e.target.files[0])}
                />
              </div>

              <button
                disabled={isLoading}
                className="w-full py-2 bg-green-600 text-white rounded hover:bg-green-700 transition-colors flex items-center justify-center gap-2"
              >
                {isLoading && (
                  <LoaderCircleIcon className="animate-spin size-4 text-white" />
                )}
                {isLoading ? "Uploading..." : "Upload Resume"}
              </button>
              <XIcon
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 cursor-pointer transition-colors"
                onClick={() => {
                  setShowUploadResume(false);
                  setTitle("");
                }}
              />
            </div>
          </form>
        )}

        {editResumeId && (
          <form
            onSubmit={editTitle}
            onClick={() => setEditResumeId("")}
            className="fixed inset-0 bg-black/70 backdrop-blur bg-opacity-50 z-10 flex items-center justify-center"
          >
            <div
              onClick={(e) => e.stopPropagation()}
              className="relative bg-slate-50 border shadow-md rounded-lg w-full max-w-sm p-6"
            >
              <h2 className="text-xl font-bold mb-4">Edit Resume Title</h2>
              <input
                onChange={(e) => setTitle(e.target.value)}
                value={title}
                type="text"
                placeholder="Enter resume title"
                className="w-full px-4 py-2 mb-4 focus:border-green-600 ring-green-600"
                required
              />

              <button className="w-full py-2 bg-green-600 text-white rounded hover:bg-green-700 transition-colors">
                Update
              </button>
              <XIcon
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 cursor-pointer transition-colors"
                onClick={() => {
                  setEditResumeId("");
                  setTitle("");
                }}
              />
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

